@push('scripts')<script>const button=document.getElementById('detect-location'),status=document.getElementById('location-status'),lat=document.getElementById('latitude'),lon=document.getElementById('longitude'),accuracy=document.getElementById('accuracy');button.addEventListener('click',()=>{if(!navigator.geolocation){status.textContent='Tento prohlížeč neumí zjistit polohu.';return}button.disabled=true;status.textContent='Zjišťuji polohu…';navigator.geolocation.getCurrentPosition(p=>{lat.value=p.coords.latitude.toFixed(7);lon.value=p.coords.longitude.toFixed(7);accuracy.value=Math.round(p.coords.accuracy);status.textContent=`Poloha načtena s přesností přibližně ${Math.round(p.coords.accuracy)} m.`;button.disabled=false},()=>{status.textContent='Polohu se nepodařilo načíst. Povolte přístup nebo vyplňte souřadnice.';button.disabled=false},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})});</script>@endpush
